local M = {}

local function link(group)
  return { link = group }
end

local function get_color(colors, color_name, fallback)
  if type(color_name) ~= "string" then
    return fallback
  end

  if colors[color_name] then
    return colors[color_name]
  end

  if color_name:match("^#%x%x%x%x%x%x$") then
    return color_name
  end

  return fallback
end

local function clear_backgrounds(groups, group_names)
  for _, group_name in ipairs(group_names) do
    if groups[group_name] then
      groups[group_name].bg = nil
    end
  end
end

